  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(18, 24, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefc;
      --muted: #9fb0cd;
      --accent: #7c9cff;
      --accent-strong: #9bb2ff;
      --error: #ff7b8f;
      --field-bg: rgba(15, 23, 42, 0.95);
      --field-border: rgba(148, 163, 184, 0.24);
      --field-border-focus: rgba(124, 156, 255, 0.95);
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 28%),
        linear-gradient(180deg, #11172b 0%, #090d19 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 520px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    .eyebrow {
      margin: 0 0 10px;
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--accent-strong);
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.9rem, 4vw, 2.5rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.95rem;
      font-weight: 600;
    }

    input {
      width: 100%;
      padding: 14px 15px;
      border: 1px solid var(--field-border);
      border-radius: 14px;
      background: var(--field-bg);
      color: var(--text);
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #6f7f9d;
    }

    input:focus {
      outline: none;
      border-color: var(--field-border-focus);
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.16);
      transform: translateY(-1px);
    }

    .helper-text,
    .error-message {
      min-height: 1.1rem;
      font-size: 0.88rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      color: var(--error);
    }

    .form-field.invalid input {
      border-color: rgba(255, 123, 143, 0.9);
      box-shadow: 0 0 0 4px rgba(255, 123, 143, 0.12);
