</head>
<body>
  <main class="support-card">
    <p class="eyebrow">Support</p>
    <h1>Contact our team</h1>
    <p class="intro">Send us your question and we will get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="fullName">Full name</label>
        <input id="fullName" name="fullName" type="text" placeholder="Jordan Lee" required>
        <p class="error-message" data-for="fullName" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" placeholder="jordan@example.com" required>
        <p class="error-message" data-for="email" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" placeholder="+1 555-123-4567" aria-describedby="phone-helper">
        <p id="phone-helper" class="helper-text">Optional. Use digits and separators such as spaces, dashes, or parentheses, for example: +1 555-123-4567.</p>
        <p class="error-message" data-for="phone" aria-live="polite"></p>
      </div>

      <button type="submit">Submit</button>
      <p class="success-message" id="form-success" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const successMessage = document.getElementById('form-success');

    const validators = {
      fullName(value) {
        if (!value.trim()) {
          return 'Full name is required.';
        }

        if (value.trim().length < 2) {
          return 'Enter your full name.';
        }

        return '';
      },
      email(value) {
        const trimmedValue = value.trim();
        if (!trimmedValue) {
          return 'Email address is required.';
        }

        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(trimmedValue)) {
          return 'Enter a valid email address.';
        }

        return '';
      },
      phone(value) {
        const trimmedValue = value.trim();
        if (!trimmedValue) {
          return '';
        }

        const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
        if (!phonePattern.test(trimmedValue)) {
          return 'Enter a valid phone number, for example +1 555-123-4567.';
        }

        return '';
      }
    };

    function setFieldState(field, message) {
      const wrapper = field.closest('.form-field');
      const errorElement = wrapper.querySelector('.error-message');
      const hasError = Boolean(message);

      wrapper.classList.toggle('invalid', hasError);
      field.setAttribute('aria-invalid', hasError ? 'true' : 'false');
      errorElement.textContent = message;
    }

    function validateField(field) {
      const validator = validators[field.name];
      const message = validator ? validator(field.value) : '';
      setFieldState(field, message);
      return !message;
    }

    form.querySelectorAll('input').forEach((field) => {
      field.addEventListener('blur', () => validateField(field));
      field.addEventListener('input', () => {
        if (field.closest('.form-field').classList.contains('invalid')) {
          validateField(field);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      successMessage.textContent = '';

      const fields = Array.from(form.querySelectorAll('input'));
      const allValid = fields.every(validateField);

      if (!allValid) {
        const firstInvalidField = form.querySelector('.form-field.invalid input');
        if (firstInvalidField) {
          firstInvalidField.focus();
        }
        return;
      }

      successMessage.textContent = 'Your message is ready to send.';
      form.reset();
      fields.forEach((field) => setFieldState(field, ''));
    });
  </script>
</body>
</html>
